unsafe fn uni2char(uni: u32, out: *mut u8, boundlen: i32) -> i32 {
    if boundlen <= 0 { return -36; }
    let ch=(uni & 0xff00)>>8; let cl=(uni&0xff) as usize;
    let p=match ch {0=>Some(&PAGE00),1=>Some(&PAGE01),3=>Some(&PAGE03),5=>Some(&PAGE05),0x20=>Some(&PAGE20),0x22=>Some(&PAGE22),0x23=>Some(&PAGE23),0x25=>Some(&PAGE25),_=>None};
    if let Some(page)=p { let v=page[cl]; if v!=0 { unsafe{*out=v;} return 1; } } -22
}
unsafe fn char2uni(rawstring: *const u8, _boundlen: i32, uni: *mut u32) -> i32 {
    unsafe {*uni=CHARSET2UNI[*rawstring as usize] as u32; if *uni==0{return -22;} } 1
}

